,\"cta\":{\"label\":\"Upgrade Now\",\"url\":\"https:\\/\\/go.elementor.com\\/go-pro-home-sidebar-upgrade\\/\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-crown.svg\"},\"repeater\":[{\"title\":\"Popup Builder\"},{\"title\":\"Custom Code & CSS\"},{\"title\":\"E-commerce Features\"},{\"title\":\"Collaborative Notes\"},{\"title\":\"Form Submission\"},{\"title\":\"Form Integrations\"},{\"title\":\"Custom Attributes\"},{\"title\":\"Role Manager\"}]}},{\"license\":[\"one\"],\"is_enabled\":\"false\",\"type\":\"default\",\"data\":{\"header\":{\"title\":\"Bring your vision to life\",\"description\":\"Get complete design flexibility for your website with Elementor Pro\'s advanced tools and premium features.\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/update-sidebar.svg\"},\"cta\":{\"label\":\"Upgrade Now\",\"url\":\"https:\\/\\/go.elementor.com\\/go-pro-home-sidebar-upgrade\\/\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-crown.svg\"},\"repeater\":[{\"title\":\"Popup Builder\"},{\"title\":\"Custom Code & CSS\"},{\"title\":\"E-commerce Features\"},{\"title\":\"Collaborative Notes\"},{\"title\":\"Form Submission\"},{\"title\":\"Form Integrations\"},{\"title\":\"Custom Attributes\"},{\"title\":\"Role Manager\"}]}}],\"external_links\":[{\"label\":\"Help Center\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-question-mark.svg\",\"url\":\"https:\\/\\/elementor.com\\/help\\/\"},{\"label\":\"Youtube\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-youtube.svg\",\"url\":\"https:\\/\\/www.youtube.com\\/@Elementor\"},{\"label\":\"Facebook Community\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-community.svg\",\"url\":\"https:\\/\\/www.facebook.com\\/groups\\/Elementors\"},{\"label\":\"Blog\",\"image\":\"https:\\/\\/assets.elementor.com\\/home-screen\\/v1\\/images\\/icon-academic-hat.svg\",\"url\":\"https:\\/\\/elementor.com\\/blog\\/\"}],\"site_builder\":[{\"hasInput\":true,\"title\":\"From idea to website in minutes\",\"placeholder\":\"What site do you want to build?\",\"buttonLabel\":\"Create my site\"},{\"hasInput\":false,\"title\":\"From idea to website in minutes\",\"text\":\"Review your brief and generate your website\",\"buttonLabel\":\"Create site\"},{\"hasInput\":false,\"title\":\"Let\'s turn your sitemap into a design\",\"text\":\"Your sitemap is waiting for you to continue.\",\"buttonLabel\":\"Visit sitemap\"},{\"hasInput\":false,\"title\":\"Your site design is waiting\",\"text\":\"Jump back in to review, edit, and add to Elementor.\",\"buttonLabel\":\"Review design\"},{\"hasInput\":false,\"title\":\"Your site design is ready to go live\",\"text\":\"Review and publish your site to continue editing in Elementor.\",\"buttonLabel\":\"Review & publish\"},{\"hasInput\":true,\"title\":\"Expand your site with Elementor AI\",\"placeholder\":\"Which page do you want to create?\",\"buttonLabel\":\"Create page\"},{\"hasInput\":true,\"title\":\"Expand your site with Elementor AI\",\"placeholder\":\"Which page do you want to create?\",\"buttonLabel\":\"Create page\"}]}\";}','off');
