INSERT INTO `wp_posts` VALUES (219,1,'2026-10-01 19:19:53','2026-10-01 19:19:53','<img width=\"88\" height=\"17\" src=\"http://portfolio-website.local/wp-content/uploads/2026/09/hero-shape-1-1.png\" alt=\"\" />																<h2>Desinging A Better World Today</h2>		<p>The best solution to build a Digital Agency &amp; Portfolio website to showcase your work professionally and effectively.</p>								<a href=\"#\">\n									Get in Touch\n					</a>\n																			<img width=\"227\" height=\"88\" src=\"http://portfolio-website.local/wp-content/uploads/2026/09/Screenshot_12-1-2025_15112_pofolio.wpolive.com-removebg-preview.png\" alt=\"\" />																<h2>5k+ Happy Clients</h2>		<p>We have many client projects</p>													<img width=\"716\" height=\"846\" src=\"http://portfolio-website.local/wp-content/uploads/2026/09/hero-img.png\" alt=\"\" srcset=\"http://portfolio-website.local/wp-content/uploads/2026/09/hero-img.png 716w, http://portfolio-website.local/wp-content/uploads/2026/09/hero-img-254x300.png 254w\" sizes=\"(max-width: 716px) 100vw, 716px\" />																		\n			<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" id=\"DESIGN\" width=\"800px\" height=\"800px\" viewBox=\"0 0 1800 1800\" xml:space=\"preserve\"><g id=\"Layer\">	<g>		<path fill=\"#333333\" d=\"M1541.606,1540.146l0.009-0.008c35.598-35.594,35.598-93.52,0-129.121   c-17.24-17.236-40.178-26.745-64.569-26.745c-24.378,0-47.314,9.509-64.564,26.763c-35.588,35.584-35.588,93.51,0.009,129.104   C1448.096,1575.73,1506.014,1575.73,1541.606,1540.146z M1440.885,1511.743c-9.656-9.655-14.975-22.498-14.975-36.165   c0-13.659,5.318-26.511,14.975-36.167c9.665-9.655,22.512-14.979,36.175-14.979c13.659,0,26.497,5.323,36.161,14.979   c19.938,19.945,19.938,52.387-0.008,72.332C1493.271,1531.689,1460.831,1531.681,1440.885,1511.743z\"></path>		<path fill=\"#333333\" d=\"M1700.934,402.736c0.021-0.026,0.047-0.043,0.068-0.065c0.044-0.043,0.083-0.091,0.127-0.134l5.504-5.505   l